import { Range, List, Seq } from '../src/immutable';

describe('issue 2006: filter followed by slice with negative begin', () => {
  it('returns last two filtered values', () => {
    expect(Range(0, 10).filter($ => true).slice(-2).toArray()).toEqual([8, 9]);
  });
  it('slice with negative end on filtered seq', () => {
    expect(Range(0, 10).filter($ => true).slice(0, -2).toArray()).toEqual([0,1,2,3,4,5,6,7]);
  });
  it('takeLast still works', () => {
    expect(Range(0, 10).filter($ => true).takeLast(2).toArray()).toEqual([8, 9]);
  });
  it('list filter slice', () => {
    expect(List.of(1,2,3,4,5,6).filter(x => true).slice(-3).toArray()).toEqual([4,5,6]);
  });
  it('keyed seq', () => {
    expect(Seq({a:1,b:2,c:3}).filter(() => true).slice(-1).toKeyedSeq().entrySeq().toArray()).toEqual([['c',3]]);
  });
  it('filter with fewer matches than slice window', () => {
    expect(Range(0, 10).filter(x => x > 7).slice(-2).toArray()).toEqual([8, 9]);
  });
});
EOF
